      this.consume('symbol', ',');
      if (this.match('symbol', ')')) {
        break;
      }
      items.push(this.parseExpression());
    }

    this.consume('symbol', ')');
    return pyTuple(items);
  }
}

export function evaluateExpression(source) {
  const parser = new Parser(tokenize(source));
  return parser.parse();
}

