export class CliSignal extends Error {
  constructor(code, stream, output) {
    super(output);
    this.name = 'CliSignal';
    this.code = code;
    this.stream = stream;
    this.output = output;
  }
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Nested list structure\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

function isNegativeNumberToken(token) {
  return /^-(?:\d(?:[\d_]*)(?:\.\d(?:[\d_]*))?(?:[eE][+-]?\d(?:[\d_]*))?|\.\d(?:[\d_]*)(?:[eE][+-]?\d(?:[\d_]*))?|0[xX][0-9a-fA-F_]+|0[oO][0-7_]+|0[bB][01_]+)$/.test(token);
}

function looksLikeOption(token) {
  if (token === undefined || token === '-') {
    return false;
  }
  if (!token.startsWith('-')) {
    return false;
  }
  return !isNegativeNumberToken(token);
}

export function parseArgs(argv, programName) {
  let optionA;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new CliSignal(0, 'stdout', formatHelp(programName));
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    if (token === '--a') {
      const value = argv[index + 1];
      if (value === undefined || looksLikeOption(value)) {
        throw new CliSignal(2, 'stderr', formatError(programName, 'argument --a: expected one argument'));
      }
      optionA = value;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      optionA = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (optionA === undefined) {
    throw new CliSignal(2, 'stderr', formatError(programName, 'the following arguments are required: --a'));
  }

  if (extras.length > 0) {
    throw new CliSignal(2, 'stderr', formatError(programName, `unrecognized arguments: ${extras.join(' ')}`));
  }

  return { a: optionA };
}

