import { parseArgs, CliSignal } from './lib/cli.mjs';
import { evaluateExpression } from './lib/pyexpr.mjs';
import { chunked, flatten } from './lib/iterutils.mjs';
import { pyRepr } from './lib/pyrepr.mjs';
import { multiplyByTwo, pyList } from './lib/pyvalues.mjs';

function programNameFromArgv(argv) {
  const scriptPath = argv[1] ?? 'test11.mjs';
  const segments = scriptPath.split(/[\\/]/);
  return segments[segments.length - 1] || 'test11.mjs';
}

function printValue(value) {
  process.stdout.write(`${pyRepr(value)}\n`);
}

function main(argv) {
  const programName = programNameFromArgv(argv);
  const args = parseArgs(argv.slice(2), programName);

  const nested = evaluateExpression(args.a);
  const result1 = flatten(nested);
  printValue(result1);

  const result2 = chunked(result1, 2);
  printValue(result2);

  const result3 = chunked(result1, 3);
  printValue(result3);

  const nested2 = pyList(
    result2.items.map((chunk) => pyList(chunk.items.map((value) => multiplyByTwo(value)))),
  );
  const result4 = flatten(nested2);
  printValue(result4);

  const result5 = chunked(result4, 4);
  printValue(result5);
}

try {
  main(process.argv);
} catch (error) {
  if (error instanceof CliSignal) {
    const stream = error.stream === 'stderr' ? process.stderr : process.stdout;
    stream.write(error.output);
    process.exit(error.code);
  }
  throw error;
}

