import { isPyFloat, isPyInt, isPyList, isPyTuple } from './pyvalues.mjs';

function normalizeExponent(text) {
  const [mantissa, exponentPart] = text.toLowerCase().split('e');
  const sign = exponentPart.startsWith('-') ? '-' : '+';
  const digits = exponentPart.replace(/^[+-]/, '');
  return `${mantissa}e${sign}${digits.padStart(2, '0')}`;
}

function formatFloat(value) {
  if (Number.isNaN(value)) {
    return 'nan';
  }
  if (!Number.isFinite(value)) {
    return value < 0 ? '-inf' : 'inf';
  }
  if (Object.is(value, -0)) {
    return '-0.0';
  }
  if (value === 0) {
    return '0.0';
  }

  const absoluteValue = Math.abs(value);
  if (absoluteValue < 1e-4 || absoluteValue >= 1e16) {
    return normalizeExponent(value.toExponential());
  }

  const text = value.toString();
  if (!text.includes('.') && !/[eE]/.test(text)) {
    return `${text}.0`;
  }
  return /[eE]/.test(text) ? normalizeExponent(text) : text;
}

function escapeString(value, quote) {
  let output = '';

  for (const character of value) {
    if (character === quote) {
      output += `\\${quote}`;
      continue;
    }

    if (character === '\\') {
      output += '\\\\';
      continue;
    }

    if (character === '\t') {
      output += '\\t';
      continue;
    }

    if (character === '\n') {
      output += '\\n';
      continue;
    }

    if (character === '\r') {
      output += '\\r';
      continue;
    }

    const codePoint = character.codePointAt(0);
    if (codePoint < 32 || codePoint === 127) {
      output += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      continue;
    }

    output += character;
  }

  return output;
}

function formatString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  return `${quote}${escapeString(value, quote)}${quote}`;
}

export function pyRepr(value) {
  if (isPyInt(value)) {
    return value.value.toString();
  }

  if (isPyFloat(value)) {
    return formatFloat(value.value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (typeof value === 'string') {
    return formatString(value);
  }

  if (value === null) {
    return 'None';
  }

  if (isPyList(value)) {
    return `[${value.items.map(pyRepr).join(', ')}]`;
  }

  if (isPyTuple(value)) {
    if (value.items.length === 1) {
      return `(${pyRepr(value.items[0])},)`;
    }
    return `(${value.items.map(pyRepr).join(', ')})`;
  }

  return String(value);
}
